using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: Route all logging to stderr so stdout stays clean for JSON-RPC.
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services
    .AddHttpClient("weather", client =>
    {
        client.BaseAddress = new Uri("https://api.open-meteo.com");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class WeatherTools(IHttpClientFactory httpClientFactory, ILogger<WeatherTools> logger)
{
    [McpServerTool, Description("Get the current weather for a location using latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location (e.g. 47.6062)")] double latitude,
        [Description("Longitude of the location (e.g. -122.3321)")] double longitude,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching weather for ({Lat}, {Lon})", latitude, longitude);

        var client = httpClientFactory.CreateClient("weather");
        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m&temperature_unit=fahrenheit";

        var response = await client.GetStringAsync(url, cancellationToken);

        using var doc = JsonDocument.Parse(response);
        var current = doc.RootElement.GetProperty("current");
        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°F, Wind: {wind} mph";
    }

    [McpServerTool, Description("Look up geographic coordinates for a city name.")]
    public async Task<string> GeolocateCity(
        [Description("City name to look up (e.g. 'Seattle')")] string cityName,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Geocoding city: {City}", cityName);

        var client = httpClientFactory.CreateClient();
        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(cityName)}&count=1";

        var response = await client.GetStringAsync(url, cancellationToken);

        using var doc = JsonDocument.Parse(response);
        if (!doc.RootElement.TryGetProperty("results", out var results)
            || results.GetArrayLength() == 0)
        {
            return $"City '{cityName}' not found.";
        }

        var city = results[0];
        var name = city.GetProperty("name").GetString();
        var lat = city.GetProperty("latitude").GetDouble();
        var lon = city.GetProperty("longitude").GetDouble();
        var country = city.GetProperty("country").GetString();

        return $"{name}, {country} → Latitude: {lat}, Longitude: {lon}";
    }
}

